import{G as e,K as t,at as n,n as r}from"./chunks/framework.CZI4dhmU.js";var i=JSON.parse(`{"title":"概念","description":"","frontmatter":{},"headers":[],"relativePath":"architect/micro/basic/index.md","filePath":"architect/micro/basic/index.md"}`),a={name:`architect/micro/basic/index.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to “概念”">​</a></h1><ul><li>是将一个复杂的应用程序拆分为多个小型、独立运行的服务，每个服务聚焦于解决特定的业务领域问题（即 “单一职责”），并通过轻量级通信协议（如 HTTP/REST、gRPC）实现服务间协作，最终共同构成完整的业务系统。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><ul><li>一个电商平台（如淘宝）若采用微服务架构，不会是一个 “大一统” 的程序，而是拆分为： <ul><li><strong>用户服务</strong>（负责注册、登录、个人信息）、</li><li><strong>商品服务</strong>（负责商品上架、库存管理）、</li><li><strong>订单服务</strong>（负责下单、订单状态）、</li><li><strong>支付服务</strong>（负责对接支付渠道、资金流转）、</li><li><strong>物流服务</strong>（负责物流跟踪、配送管理）</li></ul></li><li>等多个独立服务，每个服务可单独开发、测试、部署。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to “特性”">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>描述</th></tr></thead><tbody><tr><td>单一职责</td><td>每个服务只专注于一个业务领域（如 “订单”“支付”），边界清晰，避免功能耦合。</td></tr><tr><td>独立自治</td><td>服务可独立开发、测试、构建、部署，不依赖其他服务的发布周期。</td></tr><tr><td>轻量级通信</td><td>服务间通过标准化、轻量级的协议通信，避免复杂的分布式技术栈。</td></tr><tr><td>数据独立存储</td><td>每个服务拥有专属的数据库（或数据库实例 / 表空间），不共享数据存储。</td></tr><tr><td>技术栈灵活选择</td><td>不同服务可根据业务需求选择最合适的技术栈（语言、框架、数据库）。</td></tr><tr><td>容错与弹性设计</td><td>服务具备故障隔离能力，单个服务故障不扩散至整个系统。</td></tr></tbody></table><h2 id="核心架构组件" tabindex="-1">核心架构组件 <a class="header-anchor" href="#核心架构组件" aria-label="Permalink to “核心架构组件”">​</a></h2><h3 id="服务拆分" tabindex="-1">服务拆分 <a class="header-anchor" href="#服务拆分" aria-label="Permalink to “服务拆分”">​</a></h3><ul><li><p>基于领域驱动设计（DDD） 思想，将业务拆分为 “领域服务”，每个服务对应一个 “限界上下文”（业务边界）。</p></li><li><p><strong>按业务功能拆分</strong>： 如电商的 “用户、商品、订单、支付”。</p></li><li><p><strong>按用户角色拆分</strong>： 如 SaaS 系统的 “租户服务、管理员服务、普通用户服务”。</p></li><li><p><strong>按数据边界拆分</strong>： 如 “订单数据” 对应订单服务，“用户数据” 对应用户服务。</p></li></ul><h3 id="服务注册-发现" tabindex="-1">服务注册/发现 <a class="header-anchor" href="#服务注册-发现" aria-label="Permalink to “服务注册/发现”">​</a></h3><ul><li>服务启动后自动注册到注册中心，其他服务通过注册中心查询服务地址（解决 “服务在哪” 问题）。</li><li>服务注册工具有：<code>Nacos</code>、<code>Eureka</code>、<code>Consul</code>、<code>Zookeeper</code>、<code>Etcd</code>。</li></ul><h3 id="api-网关" tabindex="-1">API 网关 <a class="header-anchor" href="#api-网关" aria-label="Permalink to “API 网关”">​</a></h3><ul><li>统一入口，负责路由转发、认证授权、限流熔断、日志监控（解决 “请求怎么进” 问题）。</li></ul><h3 id="配置中心" tabindex="-1">配置中心 <a class="header-anchor" href="#配置中心" aria-label="Permalink to “配置中心”">​</a></h3><ul><li>集中管理所有服务的配置（如数据库地址、接口开关），支持动态更新（避免修改配置重启服务）。</li><li>常用配置中心有：<code>Nacos</code>、<code>Apollo</code>、<code>Spring Cloud Config</code>。</li></ul><h3 id="服务通信" tabindex="-1">服务通信 <a class="header-anchor" href="#服务通信" aria-label="Permalink to “服务通信”">​</a></h3><ul><li>实现服务间的远程调用，分同步（如 REST、gRPC）和异步（如消息队列）两种模式。</li><li><strong>同步</strong>：<code>Spring Cloud OpenFeign</code>、<code>gRPC</code></li><li><strong>异步</strong>：<code>RabbitMQ</code>、<code>Kafka</code>、<code>RocketMQ</code></li></ul><h3 id="服务治理" tabindex="-1">服务治理 <a class="header-anchor" href="#服务治理" aria-label="Permalink to “服务治理”">​</a></h3><ul><li>保障服务稳定性，包括熔断（故障隔离）、降级（流量高峰时牺牲非核心功能）、限流（控制请求量）。</li><li><strong>熔断</strong>：<code>Hystrix</code>、<code>Resilience4j</code></li><li><strong>降级</strong>：<code>Sentinel</code>、<code>Hystrix</code></li><li><strong>限流</strong>：<code>Sentinel</code>、<code>Resilience4j</code></li></ul><h3 id="分布式事务" tabindex="-1">分布式事务 <a class="header-anchor" href="#分布式事务" aria-label="Permalink to “分布式事务”">​</a></h3><ul><li>解决跨服务操作的数据一致性问题（如 “下单” 需同时 “扣库存”，若一方失败需回滚）。</li><li><code>Seata（AT 模式）</code>、<code>Saga 模式</code>、<code>TCC 模式</code></li></ul><h3 id="监控与追踪" tabindex="-1">监控与追踪 <a class="header-anchor" href="#监控与追踪" aria-label="Permalink to “监控与追踪”">​</a></h3><ul><li>监控服务运行状态（如 CPU、接口响应时间），追踪跨服务请求链路（定位故障节点）。</li><li><strong>监控</strong>：<code>Prometheus</code>、<code>Grafana</code></li><li><strong>追踪</strong>：<code>Zipkin</code>、<code>Sleuth</code></li></ul>`,23)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};